#!/usr/bin/env bash
# This file is part of Witness Angel Cryptolib
# SPDX-FileCopyrightText: Copyright Prolifik SARL
# SPDX-License-Identifier: GPL-2.0-or-later
#
# Build and test the flightbox C encryptor in every configuration (design D13), on Linux or WSL:
#   - each crypto backend with both document formats, with GCC and with Clang, under ASan/UBSan: unit tests;
#   - JSON-only and CBOR-only builds on the Mbed TLS backend: unit tests, including the symbol check of the
#     disabled format;
#   - libFuzzer smoke runs of each fuzz target (Clang), from seeds generated by Python;
#   - Cortex-M4 compile-only builds (arm-none-eabi-gcc), CBOR-only and JSON-only, with their code sizes.
# The GCC builds of both backends are then usable by the interop tests:
#   WA_FLIGHTBOX_C_BUILD_DIR=<printed value> pytest reimplementations/c-language/tests/interop
#
# Environment variables (all optional):
#   WA_BUILD_ROOT       directory of the builds (default: reimplementations/c-language/build)
#   WA_CC               GCC compiler (default: gcc)
#   WA_CLANG            Clang compiler, with libFuzzer (default: clang)
#   WA_PYTHON           Python interpreter able to import wacryptolib's dependencies (default: python3)
#   WA_FUZZ_SECONDS     duration of each fuzz run (default: 60)
#   WA_CMAKE_GENERATOR  CMake generator (default: Ninja when available)

set -euo pipefail

SOURCE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPOSITORY_DIR="$(cd "$SOURCE_DIR/../.." && pwd)"
BUILD_ROOT="${WA_BUILD_ROOT:-$SOURCE_DIR/build}"
CC_GCC="${WA_CC:-gcc}"
CC_CLANG="${WA_CLANG:-clang}"
PYTHON="${WA_PYTHON:-python3}"
FUZZ_SECONDS="${WA_FUZZ_SECONDS:-60}"
FETCHCONTENT_DIR="$BUILD_ROOT/_fetchcontent"
JOBS="$(getconf _NPROCESSORS_ONLN 2>/dev/null || echo 2)"

GENERATOR_ARGUMENTS=()
if [ -n "${WA_CMAKE_GENERATOR:-}" ]; then
    GENERATOR_ARGUMENTS=(-G "$WA_CMAKE_GENERATOR")
elif command -v ninja >/dev/null 2>&1; then
    GENERATOR_ARGUMENTS=(-G Ninja)
fi

for tool in cmake "$CC_GCC" "$CC_CLANG" arm-none-eabi-gcc arm-none-eabi-size "$PYTHON"; do
    if ! command -v "$tool" >/dev/null 2>&1; then
        echo "error: '$tool' not found (see the environment variables at the top of $0)" >&2
        exit 1
    fi
done

mkdir -p "$BUILD_ROOT"

log_step() {
    echo
    echo "======== $* ========"
}

# configure_and_build BUILD_NAME [cmake arguments...] ; builds every default target
configure_and_build() {
    local build_dir="$BUILD_ROOT/$1"
    shift
    cmake -S "$SOURCE_DIR" -B "$build_dir" "${GENERATOR_ARGUMENTS[@]}" -Wno-dev \
        -DFETCHCONTENT_BASE_DIR="$FETCHCONTENT_DIR" "$@"
    cmake --build "$build_dir" --parallel "$JOBS"
}

run_unit_tests() {
    (cd "$BUILD_ROOT/$1" && ctest --output-on-failure --parallel "$JOBS")
}

# HOST BUILDS WITH UNIT TESTS #

for backend in MBEDTLS WOLFCRYPT; do
    build_name="gcc_$(echo "$backend" | tr '[:upper:]' '[:lower:]')"
    log_step "$build_name: GCC, $backend, JSON and CBOR, sanitizers"
    configure_and_build "$build_name" -DCMAKE_C_COMPILER="$CC_GCC" -DCMAKE_BUILD_TYPE=Debug \
        -DWA_CRYPTO_BACKEND="$backend" -DWA_DOCUMENT_FORMATS="JSON;CBOR" -DWA_ENABLE_SANITIZERS=ON \
        -DWA_BUILD_TOOLS=ON -DBUILD_TESTING=ON
    run_unit_tests "$build_name"
done

for document_format in JSON CBOR; do
    build_name="gcc_mbedtls_$(echo "$document_format" | tr '[:upper:]' '[:lower:]')_only"
    log_step "$build_name: GCC, MBEDTLS, $document_format only, sanitizers"
    configure_and_build "$build_name" -DCMAKE_C_COMPILER="$CC_GCC" -DCMAKE_BUILD_TYPE=Debug \
        -DWA_CRYPTO_BACKEND=MBEDTLS -DWA_DOCUMENT_FORMATS="$document_format" -DWA_ENABLE_SANITIZERS=ON \
        -DWA_BUILD_TOOLS=ON -DBUILD_TESTING=ON
    run_unit_tests "$build_name"
    if ! (cd "$BUILD_ROOT/$build_name" && ctest -N) | grep test_wa_library_symbols_of_disabled_formats >/dev/null; then
        echo "error: the symbol check of the disabled format is not registered in $build_name" >&2
        exit 1
    fi
done

for backend in MBEDTLS WOLFCRYPT; do
    build_name="clang_$(echo "$backend" | tr '[:upper:]' '[:lower:]')"
    log_step "$build_name: Clang, $backend, JSON and CBOR, sanitizers"
    configure_and_build "$build_name" -DCMAKE_C_COMPILER="$CC_CLANG" -DCMAKE_BUILD_TYPE=Debug \
        -DWA_CRYPTO_BACKEND="$backend" -DWA_DOCUMENT_FORMATS="JSON;CBOR" -DWA_ENABLE_SANITIZERS=ON \
        -DWA_BUILD_TOOLS=ON -DBUILD_TESTING=ON
    run_unit_tests "$build_name"
done

# FUZZING #

log_step "clang_fuzz: libFuzzer targets, $FUZZ_SECONDS s each"
configure_and_build clang_fuzz -DCMAKE_C_COMPILER="$CC_CLANG" -DCMAKE_BUILD_TYPE=RelWithDebInfo \
    -DWA_CRYPTO_BACKEND=MBEDTLS -DWA_BUILD_FUZZERS=ON -DWA_BUILD_TOOLS=OFF -DBUILD_TESTING=OFF
FUZZ_DIR="$BUILD_ROOT/clang_fuzz"
rm -rf "$FUZZ_DIR/fuzz_seeds" "$FUZZ_DIR/fuzz_artifacts"
(cd "$REPOSITORY_DIR" && PYTHONPATH="$REPOSITORY_DIR/src${PYTHONPATH:+:$PYTHONPATH}" \
    "$PYTHON" "$SOURCE_DIR/tests/fuzz/generate_fuzz_seed_corpora.py" "$FUZZ_DIR/fuzz_seeds")
for seed_name in wacbor_subprofile_decoder device_profile_loader; do
    target="wa_fuzz_$seed_name"
    corpus_dir="$FUZZ_DIR/fuzz_corpus/$target"
    artifact_dir="$FUZZ_DIR/fuzz_artifacts/$target/"
    mkdir -p "$corpus_dir" "$artifact_dir"
    echo "Fuzzing $target for $FUZZ_SECONDS s"
    "$FUZZ_DIR/$target" -max_total_time="$FUZZ_SECONDS" -timeout=30 -rss_limit_mb=4096 -print_final_stats=1 \
        -artifact_prefix="$artifact_dir" "$corpus_dir" "$FUZZ_DIR/fuzz_seeds/$seed_name" \
        >"$FUZZ_DIR/$target.log" 2>&1 || {
        tail -n 60 "$FUZZ_DIR/$target.log"
        echo "error: $target found a failure, see $artifact_dir" >&2
        exit 1
    }
    grep -a "DONE\|stat::number_of_executed_units" "$FUZZ_DIR/$target.log"
    if [ -n "$(ls -A "$artifact_dir")" ]; then
        echo "error: $target left artifacts in $artifact_dir" >&2
        exit 1
    fi
done

# CROSS-COMPILATION #

for document_format in CBOR JSON; do
    build_name="cortex_m4_$(echo "$document_format" | tr '[:upper:]' '[:lower:]')_only"
    log_step "$build_name: arm-none-eabi-gcc, Cortex-M4, MBEDTLS, $document_format only"
    cmake -S "$SOURCE_DIR" -B "$BUILD_ROOT/$build_name" "${GENERATOR_ARGUMENTS[@]}" -Wno-dev \
        -DFETCHCONTENT_BASE_DIR="$FETCHCONTENT_DIR" \
        -DCMAKE_TOOLCHAIN_FILE="$SOURCE_DIR/cmake/wa_arm_cortex_m4_toolchain.cmake" \
        -DWA_CRYPTO_BACKEND=MBEDTLS -DWA_LIBRARY_ONLY=ON -DWA_DOCUMENT_FORMATS="$document_format"
    cmake --build "$BUILD_ROOT/$build_name" --parallel "$JOBS" --target wa_flightbox mbedcrypto wa_mlkem_native
    (cd "$BUILD_ROOT/$build_name" && for library in libwa_flightbox.a libwa_mlkem_native.a \
        $(find . -name libmbedcrypto.a); do
        echo "$library: $(arm-none-eabi-size -t "$library" | tail -n 1)"
    done)
done

log_step "All builds and tests passed"
echo "Interop builds: WA_FLIGHTBOX_C_BUILD_DIR=$BUILD_ROOT/gcc_mbedtls:$BUILD_ROOT/gcc_wolfcrypt"
